using System.Numerics;
using System.Runtime.CollectionsMarshal;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, double> _prices = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _productsByCategory = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, double price)
    {
        _categories[code] = category;
        _prices[code] = price;

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_productsByCategory, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    /// <summary>
    /// Computes total price for a batch of codes using SIMD-accelerated summation.
    /// </summary>
    public double GetTotalPrice(ReadOnlySpan<string> codes)
    {
        // Collect matching prices into a contiguous buffer for vectorized sum
        int count = codes.Length;
        double[] buffer = count <= 256 ? stackalloc double[0].Length == 0 ? new double[count] : new double[count] : new double[count];
        Span<double> prices = buffer.AsSpan(0, count);

        int found = 0;
        for (int i = 0; i < codes.Length; i++)
        {
            ref var priceRef = ref CollectionsMarshal.GetValueRefOrNullRef(_prices, codes[i]);
            if (!Unsafe.IsNullRef(ref priceRef))
                prices[found++] = priceRef;
        }

        return SimdSum(prices[..found]);
    }

    /// <summary>
    /// Overload accepting IEnumerable for backward compatibility.
    /// </summary>
    public double GetTotalPrice(IEnumerable<string> codes)
    {
        if (codes is IList<string> list)
        {
            // Fast path: avoid allocation by working over the list directly
            int count = list.Count;
            double[] buffer = new double[count];
            int found = 0;
            for (int i = 0; i < count; i++)
            {
                ref var priceRef = ref CollectionsMarshal.GetValueRefOrNullRef(_prices, list[i]);
                if (!Unsafe.IsNullRef(ref priceRef))
                    buffer[found++] = priceRef;
            }
            return SimdSum(buffer.AsSpan(0, found));
        }

        double total = 0d;
        foreach (var code in codes)
        {
            ref var priceRef = ref CollectionsMarshal.GetValueRefOrNullRef(_prices, code);
            if (!Unsafe.IsNullRef(ref priceRef))
                total += priceRef;
        }
        return total;
    }

    /// <summary>
    /// O(1) category lookup via reverse index instead of O(n) linear scan.
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        if (_productsByCategory.TryGetValue(category, out var products))
            return new List<string>(products);
        return new List<string>();
    }

    /// <summary>
    /// SIMD-accelerated double summation using hardware vectors.
    /// </summary>
    private static double SimdSum(ReadOnlySpan<double> values)
    {
        if (values.IsEmpty)
            return 0d;

        ReadOnlySpan<double> remaining = values;
        double sum = 0d;

        if (Vector.IsHardwareAccelerated && remaining.Length >= Vector<double>.Count)
        {
            var vsum = Vector<double>.Zero;
            var vectors = MemoryMarshal.Cast<double, Vector<double>>(remaining);

            for (int i = 0; i < vectors.Length; i++)
                vsum += vectors[i];

            sum = Vector.Sum(vsum);
            remaining = remaining[(vectors.Length * Vector<double>.Count)..];
        }

        // Scalar tail
        for (int i = 0; i < remaining.Length; i++)
            sum += remaining[i];

        return sum;
    }
}

